"""Candidate sequence; unresolved inspection/commissioning dependencies remain explicit."""
import json,copy,hashlib
from pathlib import Path
P=Path(__file__).parent
d=json.loads((P/'valve-inspection-candidate-v1.procedure.json').read_text())
inspection={s['id']:s for s in d['steps']}
ss=[]
def add(i,t,a,p,record=False,diagram=False):
    ss.append(dict(id=i,title=t,instruction=a,depends_on=[ss[-1]['id']] if ss else [],source_pdf_pages=p,verification=['Record the observed result and resolve any failed condition before continuing.' if record else 'Action complete with parts correctly located.'],record_required=record,diagram_reference_required=diagram,source_links=[d['source']['source_url']+'#page='+str(x) for x in p],origin='Original source-based summary; dependency gates are application workflow.'))
def old(i):
    x=copy.deepcopy(inspection[i]); x['depends_on']=[ss[-1]['id']] if ss else []; ss.append(x)
add('scope','Confirm the planned piston work','This candidate covers stock piston, ring and cylinder removal/refit while retaining a serviceable cylinder head and bottom end. Before teardown, arrange qualified dimensional inspection and exact replacement parts. Head valve/guide/seat repair, machining, crankshaft repair and post-rebuild running clearance are not supplied by this candidate. It is not released for guided use.',[52,55],True)
for i in ['cold','seat','shrouds','tank-release','tank-hang']:old(i)
add('side-covers','Remove the side covers','Remove each side-cover bolt and slide the cover rearward to release its hook and tab.',[11])
add('muffler-out','Remove the standard muffler','Loosen the joint band. Remove mounting bolt B and its washer, then mounting bolt A. Support and withdraw the muffler; remove the joint gasket.',[16],diagram=True)
add('pipe-out','Remove the exhaust pipe','Remove the head joint nuts, exhaust pipe and port gasket. Retain the nuts and protect the open port.',[17])
add('airbox-lid','Open rear-frame access','Remove the air-cleaner lid bolt, release its tabs and remove the lid.',[13])
add('airbox-wires','Release the airbox attachments','Release the ECM suspension tab and lift the ECM from the airbox. Disconnect the black IAT 2P connector and release its wire protector and wire clip. Remove the regulator/rectifier and starter/main-relay mounting bolts and support the assembly clear without pulling its wires.',[14],diagram=True)
add('rear-frame-out','Remove the rear-frame assembly','Disconnect the crankcase breather from the airbox and loosen the connecting-tube band at the throttle body. Support the rear frame, remove its upper and lower bolts, release the connecting tube and lift the rear-frame/airbox assembly clear. Leave the fender and airbox assembled for this operation.',[14],diagram=True)
for i in ['plug','cover-out','tdc','intake','exhaust']:old(i)
add('tensioner-lock','Retract and lock the tensioner','Remove the tensioner-lifter cap bolt and sealing washer. Use stopper 070MG-0010100 or US 07AMG-001A100; turn it clockwise to its stop, then push the tabs into the grooves to retain the retracted tensioner.',[46],diagram=True)
add('holder-out','Remove the cam holder','Remove the holder bolts and lift the holder while retaining the bearing set rings. Keep all small parts away from the crankcase opening.',[46])
add('cam-out','Remove the camshaft','Remove the set rings. Slide the left bearing toward the sprocket until it contacts it and remove the right bearing. Release the chain from the sprocket and lift out the cam. Secure the chain with wire so it cannot fall inside.',[47],diagram=True)
add('shims-out','Record and remove the shims','Use a magnet or tweezers to remove each shim without damaging intake rockers. Preserve its original position. Wipe off oil, measure actual thickness with a micrometer and record each value with the corresponding cold clearance.',[47],True)
add('coolant-out','Drain the cold cooling system','With the bike upright and the engine and radiator cool, remove the coolant drain bolt and sealing washer. Slowly remove the radiator cap; the upper shroud bolt is already removed. Lean the machine each way several times to finish draining.',[52])
add('rockers-out','Remove the rocker arms','Pull the intake rocker shaft and remove both intake rockers, preserving left/right identity. Temporarily thread a suitable 8 mm bolt into the exhaust rocker shaft to withdraw it. Remove both exhaust rockers, then remove the temporary bolt.',[52],diagram=True)
add('head-access','Release the head attachments','Disconnect the ignition-coil primary connectors and remove the coil and mounting bolts. Loosen the insulator band, release the throttle body and support it without loading its hoses or cables. Remove the head hanger bolts, plate bolts, plates and collar. Disconnect the black ECT 2P connector and release radiator hose A after loosening its band.',[53],diagram=True)
add('head-out','Remove the cylinder head','Remove the head 6 mm bolt. Loosen the four main head bolts in a crisscross pattern over two or three stages. Remove the rear bolts and washers. Lift the head enough to remove the front bolts and washers, then lift it off while retaining the chain. Remove dowels and gasket.',[53,54],diagram=True)
add('cylinder-out','Remove the cylinder','Remove the chain guide. Lift the cylinder while supporting the piston and retaining the chain. Remove the base gasket and dowels without dropping them into the case.',[54])
add('piston-out','Remove the piston','Protect the crankcase opening with a shop towel. Remove the pin clips and press the pin out without damaging it or the piston. Remove the piston. Spread rings only as far as necessary and lift them off opposite each gap. Do not polish the pin.',[55])
add('dimensional-review','Inspect and measure the removed parts','Inspect the cylinder, piston, rings, pin and connecting-rod small end for damage, abnormal wear or deformation. Record actual measurements and acceptance against handbook page 2-37. Piston diameter is measured 5 mm above the skirt bottom. This candidate does not supply the complete metrology technique; obtain qualified inspection before fitting parts. Replace parts outside their applicable service limits; do not continue with an unresolved head, rod or cylinder defect.',[55],True)
add('rings-in','Install the rings','Clean grooves without damage and oil the entire ring surfaces. Fit the spacer then side rails; fit the top ring with its mark upward. Use the page 2-38 drawing: top-ring and upper-rail gaps are 180 degrees apart and oil-ring gaps are 90 degrees apart. Verify rings rotate freely without sticking.',[56],True,True)
add('piston-in','Install the piston and new clips','Protect the case opening. Apply molybdenum oil solution to the rod small-end inner surface and pin outer surface; use engine oil on the piston exterior and pin hole. Molybdenum oil solution is equal parts engine oil and molybdenum grease. Face the IN mark and large valve recesses toward intake. Insert the pin and NEW clips; seat both fully with their gaps away from piston cutouts.',[4,56,57],diagram=True)
add('base-seal','Prepare the cylinder base','Clean the mating surface. Apply TB1141G by ThreeBond or equivalent to the case-side split-line patches shown on page 2-39, following the illustrated 5–10 mm extent on each side. Fit dowels and a NEW base gasket. Do not apply an invented bead size elsewhere.',[57],diagram=True)
add('cylinder-in','Install the cylinder','Oil the bore, piston exterior and rings. Route the chain and tensioner through the cylinder and compress the rings by hand while lowering the cylinder over the supported piston. Avoid damaging the rings.',[58])
add('guide-in','Install the chain guide','Inspect the guide slipper and replace it if worn or damaged. Engage its tabs with the cylinder grooves and its lower end with the crankcase groove.',[58],diagram=True)
add('head-in','Install the retained head','Fit dowels and a NEW head gasket. Apply engine oil to the front main-head-bolt threads and seating surfaces. Put those bolts and washers into the head before lowering the head onto the cylinder, retaining the chain.',[58],diagram=True)
add('head-tighten','Tighten the head','Oil the rear main-head-bolt threads and seating surfaces and install them with washers. Tighten all four main bolts to 50 Nm in crisscross order over two or three stages. Install the separate 6 mm head bolt securely.',[59],True)
add('head-connections','Restore the head connections','Refit radiator hose A with the band-end gap at 0–0.5 mm as shown. Reconnect the black ECT 2P connector. Install hanger plates and collar; tighten hanger bolts FIRST to 54 Nm, then plate bolts to 32 Nm.',[59,60],diagram=True)
add('throttle-in','Refit the throttle body and coil','Engage the throttle-body lug in the insulator groove and the band hole over its locating boss. Tighten the band screw until both ends fully seat on the collar. Install the ignition coil and secure its bolts; restore both primary connectors.',[60],diagram=True)
add('rockers-in','Install the rocker arms','Apply molybdenum oil solution to exhaust-rocker inner and shim slipper surfaces; install left/right with identifying marks outward. Use the temporary 8 mm bolt to position the exhaust shaft with its cutout as drawn, then remove the bolt. Lubricate intake-rocker inner, cam slipper and shim slipper surfaces; install left/right with marks facing right, never upside down. Position its shaft cutout as drawn.',[4,61],diagram=True)
add('shim-select','Select and install the shims','Use the recorded cold readings and actual shim thicknesses: new thickness = measured clearance − specified clearance + old thickness. Intake target is 0.13 mm; exhaust target is 0.28 mm. Available shims run 1.200–3.000 mm in 0.025 mm increments. Measure each chosen shim with a micrometer and install it in its recorded position. A calculation beyond the available range or suspected valve-seat/carbon problem requires excluded repair before proceeding.',[44,45,47,48],True)
add('cam-check','Check the decompressor and timing','Confirm the primary T mark is still aligned. Check the decompressor weight and spring: after finger movement, it must return automatically. An abnormal mechanism requires repair outside this candidate. Apply molybdenum oil solution to cam lobes. Install the cam with intake lobes up, decompressor weight and sprocket lines as shown on page 2-30, and engage the chain.',[48],True,True)
add('bearings-in','Seat the cam bearings and holder','Seat the left bearing against the cam rib; install the right bearing. Fit both set rings into their bearing grooves. Align holder grooves to the rings and dowels to head holes; align rocker-shaft cutouts with holder bolt holes.',[48,49],diagram=True)
add('holder-in','Tighten the holder','Oil holder-bolt threads and seating surfaces. The exhaust-side bolts are long and intake-side bolts short. Tighten them to 15 Nm.',[49],True)
add('tensioner-release','Release and oil the tensioner','Remove the stopper. Through the bolt hole apply MORE THAN 2.0 cm³ of engine oil onto the slit surface of the tensioner shaft. Install a NEW sealing washer and secure the cap bolt.',[49],diagram=True)
add('clearance-repeat','Rotate and remeasure','Turn the crankshaft clockwise several revolutions to settle the shims. Return to compression TDC using the T mark, sprocket lines and decompressor orientation. Remeasure all four cold clearances at the same measurement locations. Record results. If any reading is outside its range, repeat the reviewed tensioner/cam/shim selection and refit sequence before closure; never run an engine with an unresolved result.',[44,45,49],True,True)
for i in ['access-cap','cover-seals','cover-in','breather','plug-in']:old(i)
add('rear-frame-in','Refit the rear-frame assembly','Seat the connecting tube on the throttle body and loosely mount the rear frame. Tighten upper bolts FIRST to 32 Nm, then lower bolts to 44 Nm. Align the tube-band hole with its lug; set the screw dimension shown on page 1-9 to 6–9 mm. Restore the breather with clip orientation as drawn, regulator/relay mounting, wire clip/protector, black IAT 2P, ECM suspension and airbox lid.',[13,14,15],diagram=True)
add('exhaust-in','Refit the standard exhaust','Fit a NEW port gasket and loosely mount the pipe. Fit the muffler band tab into its cutout and a NEW muffler joint gasket; loosely mount the muffler with A, washer and B. Tighten pipe nuts to 20 Nm, then secure muffler mounting A before B, then tighten its joint band to 20 Nm.',[16,17],diagram=True)
add('coolant-in','Refill and bleed coolant','Install a NEW drain sealing washer and secure the drain bolt. Upright on level ground, fill to the neck with Pro Honda HP coolant or equivalent corrosion-inhibited ethylene glycol at the standard 1:1 distilled-water concentration. Listed capacities are 1.08 L at change and 1.14 L after disassembly. Lean about 20 degrees each way several times; top up and repeat if the level falls. Secure the cap.',[62],True)
old('tank-in')
add('side-covers-in','Refit the side covers','Engage each cover hook in the rear-fender groove and align its tab with the shroud slot during shroud installation. Tighten side-cover bolts to 10 Nm.',[11])
for i in ['shrouds-in','seat-in']:old(i)
add('handover','Record the static assembly result','Record accepted dimensions, shim sizes, four final clearances and completed assembly. Keep the engine stopped until post-rebuild running, leak inspection and break-in instructions have been separately confirmed. This candidate does not authorize an unreviewed first start.',[16,17,49,55,62],True)
d.update(id='honda-2026-crf450r-piston-cylinder-candidate-v1',title='Piston and cylinder service — review candidate',steps=ss,status='CANDIDATE_WITH_UNCLOSED_DEPENDENCIES',completeness='Mechanical access, piston/cylinder removal/refit and static closure sequence reviewed; complete dimensional inspection and post-rebuild commissioning remain unresolved. NOT a complete runnable rebuild guide.',required_parts=['Exact stock replacement piston/rings/pin as inspection requires','New piston-pin clips','New head and base gaskets','New tensioner-cap sealing washer','New crankshaft-hole-cap O-ring','New coolant drain sealing washer','New exhaust-port and muffler-joint gaskets','Replacement damaged seals and guide as required'],entry_state=['Candidate only: exact stock model confirmed, inspection capability and all parts ready before teardown.'],exit_state=['Static top-end assembly complete only after accepted measurements and four cold clearances.','Engine remains stopped pending separately confirmed commissioning.'],release_hold=['Current PDF-byte confirmation pending','Independent source/composition review pending','Full dimensional measurement method unresolved','First-start and break-in closure unresolved','Out-of-range clearance repeat needs explicit runtime loop/branch before release'])
d['applicability']['excluded']=['Other years, markets, RX/RWE and modified engines','Head valve/guide/seat work, machining and bottom-end repair','First-start and break-in commissioning']
d['source']['pdf_pages']=sorted({p for s in ss for p in s['source_pdf_pages']})
d['source']['printed_pages']=['Introduction / Symbols (unnumbered)' if p==4 else f'1-{p-6}' if p<19 else f'2-{p-18}' for p in d['source']['pdf_pages']]
d['required_tools'] += [dict(name=n,size=None) for n in ['Tensioner stopper 070MG-0010100 or US 07AMG-001A100','Micrometer and qualified dimensional inspection equipment','Temporary suitable 8 mm rocker-shaft bolt','Chain retaining wire','Torque wrench covering 50 and 54 Nm','Coolant container and measuring jug']]
d['consumables'] += ['Molybdenum oil solution: engine oil and molybdenum grease 1:1','TB1141G ThreeBond or equivalent','Specified coolant mixture']
(P/'piston-cylinder-candidate-v1.procedure.json').write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
print(f'Saved {len(ss)} mechanical candidate steps; explicit unreleased dependencies retained.')
